+  private TransferableBlock consumeAggregation() {
+    TransferableBlock block = _input.nextBlock();
+    while (block.isDataBlock()) {
+      _aggregationExecutor.processBlock(block);
+      sampleAndCheckInterruption();
+      block = _input.nextBlock();
+    }
+    return block;
+  }
