+      return result;
+    }
+
+    @Override
+    public boolean equals(Object obj) {
+      int[] that = ((IntArray) obj)._elements;
+      int length = _elements.length;
+      if (length != that.length) {
+        return false;
+      }
+      for (int i = 0; i < length; i++) {
+        if (_elements[i] != that[i]) {
+          return false;
+        }
+      }
+      return true;
+    }
+  }
